// Package media is the registry of RunningHub standard media models (music,
// sound, image, video, enhancement) and the schema-driven request builder.
//
// models.json is generated by scripts/gen_media_models.py from RunningHub's
// public OpenAPI docs and embedded at build time; request data never selects
// an endpoint outside this registry.
package media

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strconv"
	"strings"
	"sync"
)

type Kind string

const (
	KindMusic   Kind = "music"
	KindSFX     Kind = "sfx"
	KindT2I     Kind = "t2i"
	KindI2I     Kind = "i2i"
	KindT2V     Kind = "t2v"
	KindI2V     Kind = "i2v"
	KindR2V     Kind = "r2v"
	KindEnhance Kind = "enhance"
	KindAvatar  Kind = "avatar"
)

type Field struct {
	Name     string   `json:"name"`
	Type     string   `json:"type"`
	Enum     []string `json:"enum,omitempty"`
	Default  any      `json:"default,omitempty"`
	Min      *float64 `json:"min,omitempty"`
	Max      *float64 `json:"max,omitempty"`
	MaxItems int      `json:"max_items,omitempty"`
}

type Model struct {
	ID       string   `json:"id"`
	Name     string   `json:"name"`
	Kind     Kind     `json:"kind"`
	Family   string   `json:"family"`
	Path     string   `json:"path"`
	Channel  string   `json:"channel,omitempty"`
	Doc      string   `json:"doc"`
	Summary  string   `json:"summary"`
	Required []string `json:"required"`
	Fields   []Field  `json:"fields"`
}

//go:embed models.json
var registryJSON []byte

var (
	once   sync.Once
	models []Model
	byID   map[string]int
)

func load() {
	var doc struct {
		Models []Model `json:"models"`
	}
	if err := json.Unmarshal(registryJSON, &doc); err != nil {
		panic("media registry is invalid: " + err.Error())
	}
	models = doc.Models
	byID = make(map[string]int, len(models))
	for i, m := range models {
		byID[m.ID] = i
	}
}

// Models returns every registered model in a stable order.
func Models() []Model {
	once.Do(load)
	return append([]Model(nil), models...)
}

func Find(id string) (Model, bool) {
	once.Do(load)
	i, ok := byID[strings.TrimPrefix(strings.TrimSpace(id), "/openapi/v2/")]
	if !ok {
		return Model{}, false
	}
	return models[i], true
}

func ByKind(k Kind) []Model {
	out := []Model{}
	for _, m := range Models() {
		if m.Kind == k {
			out = append(out, m)
		}
	}
	return out
}

func (m Model) field(name string) (Field, bool) {
	for _, f := range m.Fields {
		if f.Name == name {
			return f, true
		}
	}
	return Field{}, false
}

func (m Model) required(name string) bool {
	for _, r := range m.Required {
		if r == name {
			return true
		}
	}
	return false
}

// Capabilities summarizes what the UI and planner may ask of a model.
type Capabilities struct {
	Durations   []int    `json:"durations,omitempty"`
	MinDuration int      `json:"min_duration,omitempty"`
	MaxDuration int      `json:"max_duration,omitempty"`
	Ratios      []string `json:"ratios,omitempty"`
	Resolutions []string `json:"resolutions,omitempty"`
	FirstFrame  bool     `json:"first_frame"`
	LastFrame   bool     `json:"last_frame"`
	References  int      `json:"references,omitempty"`
	NativeAudio bool     `json:"native_audio"`
	NeedsLyrics bool     `json:"needs_lyrics"`
}

func (m Model) Capabilities() Capabilities {
	var c Capabilities
	if f, ok := m.field("duration"); ok {
		for _, v := range f.Enum {
			if n, err := strconv.Atoi(v); err == nil && n > 0 {
				c.Durations = append(c.Durations, n)
			}
		}
		sort.Ints(c.Durations)
		if len(c.Durations) > 0 {
			c.MinDuration, c.MaxDuration = c.Durations[0], c.Durations[len(c.Durations)-1]
		} else if f.Min != nil && f.Max != nil {
			c.MinDuration, c.MaxDuration = int(*f.Min), int(*f.Max)
		}
	}
	for _, name := range ratioFields {
		if f, ok := m.field(name); ok {
			for _, v := range f.Enum {
				if strings.Contains(v, ":") {
					c.Ratios = append(c.Ratios, v)
				}
			}
			break
		}
	}
	for _, name := range []string{"resolution", "targetResolution"} {
		if f, ok := m.field(name); ok {
			c.Resolutions = append(c.Resolutions, f.Enum...)
			break
		}
	}
	for _, name := range firstFrameFields {
		if _, ok := m.field(name); ok {
			c.FirstFrame = true
		}
	}
	for _, name := range lastFrameFields {
		if _, ok := m.field(name); ok {
			c.LastFrame = true
		}
	}
	for _, name := range referenceFields {
		if f, ok := m.field(name); ok {
			c.References = f.MaxItems
			if c.References == 0 {
				c.References = 1
			}
		}
	}
	for _, name := range audioSwitchFields {
		if _, ok := m.field(name); ok {
			c.NativeAudio = true
		}
	}
	c.NeedsLyrics = m.required("lyrics")
	return c
}
